import math

def polygon_area(vertices):
    n = len(vertices)
    area = 0
    for i in range(n):
        j = (i + 1) % n
        area += vertices[i][0] * vertices[j][1]
        area -= vertices[j][0] * vertices[i][1]
    return abs(area) / 2.0

def find_bulkheads(C, N, vertices):
    def area_up_to_x(x):
        area = 0
        for i in range(N):
            if vertices[i][0] <= x:
                j = (i + 1) % N
                if vertices[j][0] > x:
                    t = (x - vertices[i][0]) / (vertices[j][0] - vertices[i][0])
                    area += (vertices[i][1] + t * (vertices[j][1] - vertices[i][1])) * (vertices[j][0] - vertices[i][0]) / 2.0
                else:
                    area += (vertices[i][0] * vertices[j][1] - vertices[j][0] * vertices[i][1]) / 2.0
        return area

    total_area = polygon_area(vertices)
    M = int(total_area // C)
    if total_area % C != 0:
        M += 1

    bulkheads = []
    low, high = vertices[0][0], vertices[-1][0]
    for _ in range(M - 1):
        mid = (low + high) / 2.0
        if area_up_to_x(mid) < (M - 1) * C:
            low = mid
        else:
            high = mid
        bulkheads.append(mid)

    return M, sorted(bulkheads)

